tinymce.PluginManager.add("polls",(function(t){t.addCommand("WP-Polls-Insert_Poll",(function(){for(var n=(prompt(tinymce.translate("Enter Poll ID"))||"").trim();isNaN(n);)n=(prompt(tinymce.translate("Error: Poll ID must be numeric")+"\n\n"+tinymce.translate("Please enter Poll ID again"))||"").trim();n>=-1&&null!=n&&""!=n&&t.insertContent('[poll id="'+n+'"]')})),t.addButton("polls",{text:!1,tooltip:tinymce.translate("Insert Poll"),icon:"polls dashicons-before dashicons-chart-bar",onclick:function(){tinyMCE.activeEditor.execCommand("WP-Polls-Insert_Poll")}})}));